package com.lianxibu.site.service.learning;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.service.identity.IdentityService.Actor;
import java.util.*;
import org.junit.jupiter.api.Test;

class OwnerAnswerReadServiceTest {
 final Actor owner=new Actor("fictional-owner","owner");
 static OwnerAnswerReadService.Snapshot snapshot(String state,String answer,boolean known,byte[] hash,Boolean pkg,Boolean question){return new OwnerAnswerReadService.Snapshot("fictional-package","fictional-question","Fictional title",3L,2L,state,"generated",answer,known,hash,pkg,question);}
 Map<String,Object> read(OwnerAnswerReadService.Snapshot snapshot){return new OwnerAnswerReadService((p,q)->snapshot).read(owner,"fictional-package","fictional-question");}
 @Test void ownerFirstAndWireIdentityRejectWithoutReading(){var store=mock(OwnerAnswerReadService.Store.class);var service=new OwnerAnswerReadService(store);assertThrows(OwnerAnswerReadService.Denied.class,()->service.read(new Actor("fictional-user","user"),"fictional-package","fictional-question"));assertThrows(OwnerAnswerReadService.Denied.class,()->service.read(null,"fictional-package","fictional-question"));assertThrows(IllegalArgumentException.class,()->service.read(owner,"fictional-package","bad\n"));verifyNoInteractions(store);}
 @Test void readsAllCurrentStatesAndMatchesNormalizedReviewedAnswer(){String answer="Fictional\r\nanswer";byte[] hash=AnswerLifecycleService.answerHash(answer);for(String state:List.of("draft","approved","published","withdrawn")){var data=read(snapshot(state,answer,true,hash,true,true));assertEquals(answer,data.get("answer"));assertEquals("current",data.get("review_state"));assertEquals(state.equals("published"),data.get("publicly_readable"));assertEquals(10,data.size());assertThrows(UnsupportedOperationException.class,()->data.put("history",List.of()));assertFalse(data.containsKey("review_hash"));}}
 @Test void staleUnknownAndProvenAbsentReviewRemainDifferent(){assertEquals("stale",read(snapshot("published","Fictional new",true,AnswerLifecycleService.answerHash("Fictional old"),true,true)).get("review_state"));assertEquals(false,read(snapshot("published","Fictional new",true,AnswerLifecycleService.answerHash("Fictional old"),true,true)).get("publicly_readable"));assertEquals("unreviewed",read(snapshot("draft","",true,null,true,true)).get("review_state"));var unknown=read(new OwnerAnswerReadService.Snapshot("fictional-package","fictional-question",null,null,null,null,null,null,false,null,null,null));for(String field:List.of("question_title","revision","answer_revision","answer","answer_state","generation_state","publicly_readable"))assertNull(unknown.get(field),field);assertEquals("unknown",unknown.get("review_state"));assertEquals("",read(snapshot("draft","",true,null,true,true)).get("answer"));}
 @Test void visibilityIsTriStateConjunctionNotPublishedStateAlone(){String answer="Fictional";for(Boolean visible:new Boolean[]{true,false,null}){var result=read(snapshot("published",answer,true,AnswerLifecycleService.answerHash(answer),visible,true));assertEquals(visible,result.get("publicly_readable"));}assertNull(read(snapshot("published",answer,false,null,true,true)).get("publicly_readable"));assertEquals(false,read(snapshot(null,null,false,null,false,null)).get("publicly_readable"));}
 @Test void completeIdentityAndInvalidStoredFactsFailUnavailable(){assertThrows(OwnerAnswerReadService.Missing.class,()->read(null));var bad=new OwnerAnswerReadService.Snapshot("fictional-other","fictional-question",null,null,null,null,null,null,false,null,null,null);assertThrows(OwnerAnswerReadService.Unavailable.class,()->read(bad));for(var row:List.of(snapshot("published",null,true,null,true,true),snapshot("draft","Fictional",false,new byte[32],true,true),snapshot("draft","Fictional",true,new byte[31],true,true),snapshot("Fictional unknown state","Fictional",true,null,true,true),new OwnerAnswerReadService.Snapshot("fictional-package","fictional-question",null,0L,null,null,null,null,false,null,null,null)))assertThrows(OwnerAnswerReadService.Unavailable.class,()->read(row));var service=new OwnerAnswerReadService((p,q)->{throw new IllegalArgumentException("Fictional internal detail");});assertThrows(OwnerAnswerReadService.Unavailable.class,()->service.read(owner,"fictional-package","fictional-question"));}
 @Test void hashArraysAreDefensiveAndUnicodeBoundaryIsCodepoints(){byte[] hash=AnswerLifecycleService.answerHash("Fictional answer");var row=snapshot("published","Fictional answer",true,hash,true,true);hash[0]^=1;row.reviewHash()[0]^=1;assertEquals("current",read(row).get("review_state"));assertEquals(50000,((String)read(snapshot("draft","🙂".repeat(50000),true,null,true,true)).get("answer")).codePointCount(0,100000));assertThrows(OwnerAnswerReadService.Unavailable.class,()->read(snapshot("draft","🙂".repeat(50001),true,null,true,true)));assertThrows(OwnerAnswerReadService.Unavailable.class,()->read(snapshot("draft","\uD800",true,null,true,true)));}
 @Test void oneConsistentReadUsesExplicitCompositeAndNoOtherLookup(){var store=mock(OwnerAnswerReadService.Store.class);when(store.snapshot("fictional-package","fictional-question")).thenReturn(snapshot("draft","Fictional",true,null,true,true));new OwnerAnswerReadService(store).read(owner,"fictional-package","fictional-question");verify(store).snapshot("fictional-package","fictional-question");verifyNoMoreInteractions(store);}
 @Test @SuppressWarnings("unchecked") void reviewedContractExamplesMatchProviderProjection()throws Exception{var json=tools.jackson.databind.json.JsonMapper.shared();var cases=json.readTree(java.nio.file.Files.readAllBytes(java.nio.file.Path.of("../contracts/owner-answer-wire-examples.json")));assertEquals(22,cases.size());for(var c:cases){Map<String,Object> value=json.convertValue(c.get("value"),Map.class);boolean accepted;try{OwnerAnswerReadService.validateProjection(value,"fictional-package","fictional-question");accepted=true;}catch(OwnerAnswerReadService.Unavailable invalid){accepted=false;}assertEquals(c.get("valid").booleanValue(),accepted,c.get("name").asText());}}
}
